const Cord: React.FC<{
  path: string;
  progress: number;
  color: string;
  active: boolean;
  length: number;
}> = ({ path, progress, color, active, length }) => {
  const frame = useCurrentFrame();
  const safeProgress = Math.max(0, Math.min(1, progress));
  
  // EvolvePath computes the static drawing of the line
  const { strokeDasharray, strokeDashoffset } = evolvePath(safeProgress, path);

  return (
    <svg style={{ position: "absolute", inset: 0, width: 1080, height: 1920, overflow: "visible", zIndex: 5 }}>
      {/* Outer Glow */}
      <path
        d={path}
        fill="none"
        stroke={color}
        strokeWidth="16"
        strokeDasharray={strokeDasharray}
        strokeDashoffset={strokeDashoffset}
        strokeLinecap="round"
        style={{ filter: "blur(12px)", opacity: 0.5 }}
      />
      {/* Core Line */}
      <path
        d={path}
        fill="none"
        stroke={color}
        strokeWidth="6"
        strokeDasharray={strokeDasharray}
        strokeDashoffset={strokeDashoffset}
        strokeLinecap="round"
      />
      {/* Traveling Data Pulse */}
      {active && (
        <path
          d={path}
          fill="none"
          stroke="#FFFFFF"
          strokeWidth="8"
          strokeLinecap="round"
          strokeDasharray={`40 ${length}`}
          strokeDashoffset={-((frame * 15) % (length + 40))}
          style={{ opacity: 0.9, filter: "blur(4px)" }}
        />
      )}
    </svg>
  );
};

const LeftCluster: React.FC<{
  scale: number;
  opacity: number;
  bgColor: string;
  borderColor: string;
}> = ({ scale, opacity, bgColor, borderColor }) => {
  const icons = [];
  const size = 32;
  const spacing = 48;
  for (let row = -3; row <= 3; row++) {
    for (let col = -3; col <= 3; col++) {
      const x = col * spacing;
      const y = row * spacing;
      if (x * x + y * y < 145 * 145) {
        icons.push(
          <div
            key={`${row}-${col}`}
            style={{
              position: "absolute",
              left: 180 + x - size / 2,
              top: 180 + y - size / 2,
            }}
          >
            <UserIcon color="#111111" size={size} />
          </div>
        );
      }
    }
  }

  return (
    <div
      style={{
        position: "absolute",
        left: 270 - 180,
        top: 1100 - 180,
        width: 360,
        height: 360,
        borderRadius: "50%",
        backgroundColor: bgColor,
        border: `8px solid ${borderColor}`,
        transform: `scale(${scale})`,
        opacity,
        boxShadow: `0 0 50px ${borderColor}80`,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
        zIndex: 20,
      }}
    >
      <div style={{ position: "absolute", inset: 0, borderRadius: "50%", boxShadow: "inset 0 0 30px rgba(0,0,0,0.15)" }} />
      {icons}
    </div>
  );
};

